module radix2_div (
    input wire clk,
    input wire rst,
    input wire [7:0] dividend,
    input wire [7:0] divisor,
    input wire sign,
    input wire opn_valid,
    output reg res_valid,
    input wire res_ready,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] SR;
    reg [3:0] cnt;
    reg [3:0] start_cnt;
    reg [7:0] NEG_DIVISOR;
    reg [15:0] temp_result;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            NEG_DIVISOR <= 0;
            temp_result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                abs_dividend <= (sign && (dividend[7] == 1)) ? ~dividend + 1 : dividend;
                abs_divisor <= (sign && (divisor[7] == 1)) ? ~divisor + 1 : divisor;
                SR <= {abs_dividend, 1'b0};
                NEG_DIVISOR <= ~abs_divisor + 1;
                cnt <= 4'd0;
                start_cnt <= 4'd1;
                temp_result <= 0;
            end else if (start_cnt) begin
                if (cnt == 4'd8) begin
                    cnt <= 4'd0;
                    start_cnt <= 4'd0;
                    SR <= {temp_result[7:0], temp_result[15:8]};
                    res_valid <= 1;
                end else begin
                    cnt <= cnt + 1;
                    temp_result <= SR - NEG_DIVISOR;
                    SR <= {temp_result[7:0], temp_result[15:8]};
                end
            end
        end
    end

    assign result = {SR[7:0], temp_result[7:0]};

endmodule
